BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path TO public, extensions;
SET LOCAL TimeZone = 'UTC';
SET LOCAL DateStyle = 'ISO, MDY';
SELECT no_plan();
SELECT ok(NOT has_function_privilege('anon','public.recompute_audit_v1_snapshot(uuid,uuid[],text,text)','EXECUTE'),'anon cannot recompute');
SELECT ok(NOT has_function_privilege('authenticated','public.recompute_audit_v1_snapshot(uuid,uuid[],text,text)','EXECUTE'),'authenticated cannot recompute');
SELECT ok(has_function_privilege('service_role','public.recompute_audit_v1_snapshot(uuid,uuid[],text,text)','EXECUTE'),'service role can recompute');
INSERT INTO public.audit_events(id,action_type,resource_type,details) VALUES ('15200000-0000-4000-8000-000000000301','synthetic.recompute','test','{"message":"合成"}');
SELECT set_config('snapshot.recompute',public.begin_audit_verification_snapshot(),true);
SELECT set_config('snapshot.expected',(SELECT payload->>'hash' FROM private.audit_archive_items WHERE run_id=current_setting('snapshot.recompute')::uuid AND id='15200000-0000-4000-8000-000000000301'),true);
SET LOCAL ROLE service_role;
SELECT is((public.recompute_audit_v1_snapshot(current_setting('snapshot.recompute')::uuid,ARRAY['15200000-0000-4000-8000-000000000301'::uuid],'UTC','ISO, MDY')->0->>'hash'),
  current_setting('snapshot.expected'), 'evidence-backed settings reproduce saved v1 hash');
SELECT isnt((public.recompute_audit_v1_snapshot(current_setting('snapshot.recompute')::uuid,ARRAY['15200000-0000-4000-8000-000000000301'::uuid],'Asia/Tokyo','ISO, MDY')->0->>'hash'),current_setting('snapshot.expected'),'different timezone is not silently treated as matching');
SELECT throws_ok($$ SELECT public.recompute_audit_v1_snapshot(current_setting('snapshot.recompute')::uuid,ARRAY(SELECT gen_random_uuid() FROM generate_series(1,101)),'UTC','ISO, MDY') $$,'P0001','audit_recompute_invalid','batch over 100 is rejected');
RESET ROLE;
SELECT is(current_setting('TimeZone'),'UTC','timezone restored after recompute');
SELECT is(current_setting('DateStyle'),'ISO, MDY','datestyle restored after recompute');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$ SELECT public.recompute_audit_v1_snapshot(current_setting('snapshot.recompute')::uuid,ARRAY['15200000-0000-4000-8000-000000000301'::uuid],'UTC','ISO, MDY') $$,'42501',NULL,'authenticated cannot invoke recomputation');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_ok($$ SELECT public.recompute_audit_v1_snapshot(current_setting('snapshot.recompute')::uuid,ARRAY['15200000-0000-4000-8000-000000000301'::uuid,'15200000-0000-4000-8000-000000000301'::uuid],'UTC','ISO, MDY') $$,'P0001','audit_recompute_invalid','duplicate IDs rejected');
SELECT throws_ok($$ SELECT public.recompute_audit_v1_snapshot(current_setting('snapshot.recompute')::uuid,ARRAY['15200000-0000-4000-8000-000000000399'::uuid],'UTC','ISO, MDY') $$,'P0001','audit_recompute_snapshot_mismatch','row outside snapshot rejected');
SELECT throws_ok($$ SELECT public.recompute_audit_v1_snapshot(current_setting('snapshot.recompute')::uuid,ARRAY['15200000-0000-4000-8000-000000000301'::uuid],'invalid/zone','ISO, MDY') $$,'P0001','audit_recompute_invalid','invalid timezone rejected');
SELECT throws_ok($$ SELECT public.recompute_audit_v1_snapshot(current_setting('snapshot.recompute')::uuid,ARRAY['15200000-0000-4000-8000-000000000301'::uuid],'UTC','invalid') $$,'P0001','audit_recompute_invalid','invalid datestyle rejected');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
